<?php declare(strict_types=1);
namespace App\Results;
final class BetNormalizer {
 public static function fromCard(array $b):?array{$match=trim((string)($b['match']??''));$market=mb_strtolower(trim((string)($b['market']??'')),'UTF-8');$sel=mb_strtolower(trim((string)($b['selection']??'')),'UTF-8');$odd=self::n($b['odd']??null);if($match===''||$market===''||$sel===''||$odd===null||$odd<=1)return null;$line=null;$side='';if(preg_match('/\b(over|mais\s+de|acima\s+de)\s*([0-9]+(?:[.,][0-9]+)?)/iu',$sel,$m)){$side='over';$line=(float)str_replace(',','.',$m[2]);}elseif(preg_match('/\b(under|menos\s+de|abaixo\s+de)\s*([0-9]+(?:[.,][0-9]+)?)/iu',$sel,$m)){$side='under';$line=(float)str_replace(',','.',$m[2]);}if($side===''||$line===null)return null;$type=null;if(preg_match('/escante|corner/iu',$market.' '.$sel))$type='corners_total';elseif(preg_match('/cart|card|tarjet/iu',$market.' '.$sel))$type='cards_total';elseif(preg_match('/foul|falta/iu',$market.' '.$sel))$type='fouls_total';elseif(preg_match('/gol|goal|gole/iu',$market.' '.$sel))$type='goals_total';if($type===null)return null;$teams=preg_split('/\s+(?:x|vs\.?|v)\s+/iu',$match,2);return ['home'=>trim((string)($teams[0]??''))?:null,'away'=>trim((string)($teams[1]??''))?:null,'market'=>$type,'side'=>$side,'line'=>$line,'odds'=>$odd];}
 private static function n(mixed $v):?float{if(is_numeric($v))return(float)$v;$v=str_replace(',','.',preg_replace('/[^0-9,.]/','',(string)$v)??'');return is_numeric($v)?(float)$v:null;}
}
